(414300, 36773, 8447, '<td valign="top">I like this.  The movement of the carrousel along with the stillness of the man and the ironwork help convey a sense of loss, a desire for the naive thrills of a child.  Sentimental without being a Hallmark card... hard to do.  Great job.</td>', 'I like this.  The movement of the carrousel along with the stillness of the man and the ironwork help convey a sense of loss, a desire for the naive thrills of a child.  Sentimental without being a Hallmark card... hard to do.  Great job.', '2003-09-10 09:15:44.000000', NULL, 1),
(414301, 36921, 8860, '<td valign="top">Great shot! Love the concept and despite the ugly bloke behind the glass the composition is excellent. Top mullet too - looks like a member of Slade!  :D</td>', 'Great shot! Love the concept and despite the ugly bloke behind the glass the composition is excellent. Top mullet too - looks like a member of Slade!  :D', '2003-09-10 09:18:45.000000', NULL, 1),
(414302, 36993, 11693, '<td valign="top">I like the black and white/color effect.</td>', 'I like the black and white/color effect.', '2003-09-10 09:20:25.000000', NULL, 1),
(414303, 37167, 8447, '<td valign="top">I really don''t see the point.  It could be the image size (too small) or the contrast (your neutral gray isn''t 50/50).  I like the angle, and, with some work, would like the photo, but, for this ''challenge,'' I have to rate it low.   Sorry.</td>', 'I really don''t see the point.  It could be the image size (too small) or the contrast (your neutral gray isn''t 50/50).  I like the angle, and, with some work, would like the photo, but, for this ''challenge,'' I have to rate it low.   Sorry.', '2003-09-10 09:20:27.000000', NULL, 1),
(414304, 36827, 11693, '<td valign="top">I usually like thigs out of center but in this case it feels off balance.  It is true to the theme and I like b&amp;w.</td>', 'I usually like thigs out of center but in this case it feels off balance.  It is true to the theme and I like b&w.', '2003-09-10 09:22:30.000000', NULL, 1),
(414305, 37148, 11693, '<td valign="top">Great Shot</td>', 'Great Shot', '2003-09-10 09:22:48.000000', NULL, 1),
(414306, 37055, 11693, '<td valign="top">Good color but modern background takes from the shot.</td>', 'Good color but modern background takes from the shot.', '2003-09-10 09:24:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(414310, 36805, 11693, '<td valign="top">Nice effect.</td>', 'Nice effect.', '2003-09-10 09:28:05.000000', NULL, 1),
(414311, 36730, 8447, '<td valign="top">This is wretched.  If you are going to make something with THIS MUCH BLUE then you need to get rid of any and all yellow!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!  My eye is first drawn to the tower (good), but a milisecond later I see the string of lights on the left (bad, bad, bad).  If you want it this blue, then just desaturate the damn thing, add a level of blue, and stop.</td>', 'This is wretched.  If you are going to make something with THIS MUCH BLUE then you need to get rid of any and all yellow!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!  My eye is first drawn to the tower (good), but a milisecond later I see the string of lights on the left (bad, bad, bad).  If you want it this blue, then just desaturate the damn thing, add a level of blue, and stop.', '2003-09-10 09:28:21.000000', NULL, 1),
(414312, 36741, 11693, '<td valign="top">Leaves me with a sad feeling.  Seems somewhat busy almost as if what is left after a fire.</td>', 'Leaves me with a sad feeling.  Seems somewhat busy almost as if what is left after a fire.', '2003-09-10 09:29:08.000000', NULL, 1),
(414313, 36973, 11693, '<td valign="top">Good use of color.</td>', 'Good use of color.', '2003-09-10 09:29:23.000000', NULL, 1),
(414314, 36453, 11693, '<td valign="top">Too bright.  It looks like you atempted an old picture look.  I don''t care for the overexposure.</td>', 'Too bright.  It looks like you atempted an old picture look.  I don''t care for the overexposure.', '2003-09-10 09:31:16.000000', NULL, 1),
(414315, 36559, 11693, '<td valign="top">Good exposure great theme.  I liked this shot</td>', 'Good exposure great theme.  I liked this shot', '2003-09-10 09:33:06.000000', NULL, 1),
(414316, 36949, 772, '<td valign="top">I particularly like this photograph even though I am unable to determine what it has to do with ''nostalgia''.</td>', 'I particularly like this photograph even though I am unable to determine what it has to do with ''nostalgia''.', '2003-09-10 09:33:32.000000', NULL, 1),
(414320, 37032, 3735, '<td valign="top">This is the winner  congrat !!!!    lol lol   10</td>', 'This is the winner  congrat !!!!    lol lol   10', '2003-09-10 09:38:48.000000', NULL, 1),
(414325, 37231, 772, '<td valign="top">Mabry''s Mill :)  Very nice shot... I went up there to do photos last summer and decided to postpone until the new wood had aged a little :)  Excellent shot...</td>', 'Mabry''s Mill :)  Very nice shot... I went up there to do photos last summer and decided to postpone until the new wood had aged a little :)  Excellent shot...', '2003-09-10 09:48:28.000000', NULL, 1),
(414327, 37214, 3735, '<td valign="top">I remember this.</td>', 'I remember this.', '2003-09-10 09:51:58.000000', NULL, 1),
(414331, 37183, 8447, '<td valign="top">I don''t think the medal should have been cropped as it was, but I''m giving you an 8 for creativity.</td>', 'I don''t think the medal should have been cropped as it was, but I''m giving you an 8 for creativity.', '2003-09-10 09:54:45.000000', NULL, 1),
(414334, 36297, 8447, '<td valign="top">horrible, horrible, horrible!!!!!!!!!!!!!!!!!!!!!!!!  LEARN ABOUT WHITE POINTS, neutral gray, and ''a good black.''  Damn it!  Black and White is not easy, when you people try to make ''classy'' images, you just end up looking like a moron.  One other thing, ever hear about NOT cutting the flags in two?</td>', 'horrible, horrible, horrible!!!!!!!!!!!!!!!!!!!!!!!!  LEARN ABOUT WHITE POINTS, neutral gray, and ''a good black.''  Damn it!  Black and White is not easy, when you people try to make ''classy'' images, you just end up looking like a moron.  One other thing, ever hear about NOT cutting the flags in two?', '2003-09-10 10:00:26.000000', NULL, 1),
(414338, 37158, 8447, '<td valign="top">creepy.</td>', 'creepy.', '2003-09-10 10:06:34.000000', NULL, 1),
(414341, 37032, 11693, '<td valign="top">Good shot.  I liked the headlight level perspective.</td>', 'Good shot.  I liked the headlight level perspective.', '2003-09-10 10:12:27.000000', NULL, 1),
(414342, 37102, 8447, '<td valign="top">bad writing, nice photo.</td>', 'bad writing, nice photo.', '2003-09-10 10:12:40.000000', NULL, 1),
(414345, 36812, 8643, '<td valign="top">I really like this portrait - would have preferred to avoid the shadow of the spectacles.</td>', 'I really like this portrait - would have preferred to avoid the shadow of the spectacles.', '2003-09-10 10:14:42.000000', NULL, 1),
(414346, 36822, 11693, '<td valign="top">What a great shot that almost defines the theme of this challenge.</td>', 'What a great shot that almost defines the theme of this challenge.', '2003-09-10 10:15:06.000000', NULL, 1),
(414347, 36845, 11693, '<td valign="top">Great detail and focus.  It sent me right back to the late 60''s</td>', 'Great detail and focus.  It sent me right back to the late 60''s', '2003-09-10 10:17:35.000000', NULL, 1),
(414349, 36961, 11693, '<td valign="top">I''m a sucker for a gaff rigged schooner.  I think a closer crop would be better.  Right to left adds movement.</td>', 'I''m a sucker for a gaff rigged schooner.  I think a closer crop would be better.  Right to left adds movement.', '2003-09-10 10:20:50.000000', NULL, 1),
(414350, 36627, 11693, '<td valign="top">I liked this shot.  The yellow bouy takes away from the b &amp; w look.</td>', 'I liked this shot.  The yellow bouy takes away from the b & w look.', '2003-09-10 10:23:58.000000', NULL, 1),
(414352, 37140, 772, '<td valign="top">excellent work... i think you did a good job of ''minimizing'' yourself in the reflection... great shot :) = 10</td>', 'excellent work... i think you did a good job of ''minimizing'' yourself in the reflection... great shot :) = 10', '2003-09-10 10:24:45.000000', NULL, 1),
