(414387, 37122, 10441, '<td valign="top">Nice perspective for the photo.  I love the old cross stitching.</td>', 'Nice perspective for the photo.  I love the old cross stitching.', '2003-09-10 10:53:55.000000', NULL, 1),
(414388, 36844, 10441, '<td valign="top">Good fit for the challenge.  The background is a bit too "hot", need to add some flash or use exposure compensation to bring out the faces.</td>', 'Good fit for the challenge.  The background is a bit too "hot", need to add some flash or use exposure compensation to bring out the faces.', '2003-09-10 10:55:44.000000', NULL, 1),
