(414603, 36958, 6668, '<td valign="top">Seems a little too dark on the left side, also seems a little grainy.</td>', 'Seems a little too dark on the left side, also seems a little grainy.', '2003-09-10 12:48:02.000000', NULL, 1),
(414604, 36773, 9690, '<td valign="top">good caputre of motion.  would like to see this in a quicer shutter speed as well to see some of the items on the wheel a little better (still blurring the light)  not that it would be better, but just to compare.  Great shot!!!</td>', 'good caputre of motion.  would like to see this in a quicer shutter speed as well to see some of the items on the wheel a little better (still blurring the light)  not that it would be better, but just to compare.  Great shot!!!', '2003-09-10 12:48:53.000000', NULL, 1),
(414605, 36786, 4210, '<td valign="top">I think that one of the main problems with an exposure where the sunset is in the background is that you lose alot of the detail because of shadows. Because the subject has dark skin, the problem becomes even trickier. But I like the composition and that''s one very nice sunset.</td>', 'I think that one of the main problems with an exposure where the sunset is in the background is that you lose alot of the detail because of shadows. Because the subject has dark skin, the problem becomes even trickier. But I like the composition and that''s one very nice sunset.', '2003-09-10 12:49:16.000000', NULL, 1),
(414606, 36668, 4210, '<td valign="top">I like the shades and the contrast. I like the height of this peice as well.</td>', 'I like the shades and the contrast. I like the height of this peice as well.', '2003-09-10 12:49:55.000000', NULL, 1),
(414609, 37141, 4210, '<td valign="top">A little bit blown out. The cluttered composition works well I think, and the eye is definately drawn to the lizard peice.</td>', 'A little bit blown out. The cluttered composition works well I think, and the eye is definately drawn to the lizard peice.', '2003-09-10 12:50:32.000000', NULL, 1),
(414611, 37128, 9690, '<td valign="top">looks like mars</td>', 'looks like mars', '2003-09-10 12:51:02.000000', NULL, 1),
(414612, 36538, 3569, '<td valign="top">great interpretation.  Shading right on.  Good job.</td>', 'great interpretation.  Shading right on.  Good job.', '2003-09-10 12:51:35.000000', NULL, 1),
(414613, 37059, 4210, '<td valign="top">Needs to be rotated just a touch, there''s a white line on the left side, and it''s overly brightened. But good composition, and it definately had potential.</td>', 'Needs to be rotated just a touch, there''s a white line on the left side, and it''s overly brightened. But good composition, and it definately had potential.', '2003-09-10 12:51:48.000000', NULL, 1),
(414615, 37209, 6668, '<td valign="top">The tear on the first stool is a little distracting, it takes away from the uniformity for me anyway, otherwise very nice photo, I like the sepia tones.</td>', 'The tear on the first stool is a little distracting, it takes away from the uniformity for me anyway, otherwise very nice photo, I like the sepia tones.', '2003-09-10 12:53:04.000000', NULL, 1);
