(415036, 37032, 11506, '<td valign="top">I''m picky.  I try to give only one 10 per challenge, and you''ve got it with this shot.  This would have been a "perfect 10" if the lady didn''t have sunglasses on.  I think you wouldn''t be able to tell the difference in time periods then.  Very well done.</td>', 'I''m picky.  I try to give only one 10 per challenge, and you''ve got it with this shot.  This would have been a "perfect 10" if the lady didn''t have sunglasses on.  I think you wouldn''t be able to tell the difference in time periods then.  Very well done.', '2003-09-10 18:27:23.000000', NULL, 1),
(415037, 36860, 6668, '<td valign="top">I really like this photo, and I think the border is a nice touch as well.</td>', 'I really like this photo, and I think the border is a nice touch as well.', '2003-09-10 18:28:22.000000', NULL, 1),
(415038, 37155, 11506, '<td valign="top">Overall I like this, but I think I''d like it a whole lot better on a different background.</td>', 'Overall I like this, but I think I''d like it a whole lot better on a different background.', '2003-09-10 18:30:54.000000', NULL, 1),
