(415041, 36808, 11506, '<td valign="top">Great idea.  You''d have gotten my 10 for this challenge if this was a bit more focused throughout.  The label in focus but my eye is blocked by the (out of focus) needle.</td>', 'Great idea.  You''d have gotten my 10 for this challenge if this was a bit more focused throughout.  The label in focus but my eye is blocked by the (out of focus) needle.', '2003-09-10 18:33:10.000000', NULL, 1),
(415045, 37115, 11506, '<td valign="top">This is a beautiful room.  All the light, seems a bit overpowering to me.  Nice job though.</td>', 'This is a beautiful room.  All the light, seems a bit overpowering to me.  Nice job though.', '2003-09-10 18:36:26.000000', NULL, 1),
(415049, 37182, 11506, '<td valign="top">Ah, Sim City..  the game that made me grow up and become a Transportation Planner today.  Clever idea, but I don''t know if a lot of DPC''ers will get it.  Generation gaps and such.</td>', 'Ah, Sim City..  the game that made me grow up and become a Transportation Planner today.  Clever idea, but I don''t know if a lot of DPC''ers will get it.  Generation gaps and such.', '2003-09-10 18:39:52.000000', NULL, 1),
