(415060, 37140, 11506, '<td valign="top">I can tell what you were going for... and you almost had it with this shot.  No offense but I think it''d have come out better without the relection of you taking the picture.  Otherwise good thought.</td>', 'I can tell what you were going for... and you almost had it with this shot.  No offense but I think it''d have come out better without the relection of you taking the picture.  Otherwise good thought.', '2003-09-10 18:46:05.000000', NULL, 1),
(415062, 37070, 11506, '<td valign="top">I only give out one 10 per challenge and you would have gotten it if the candle wasn''t quite as bright and distracting.  I think the border adds a nice touch.  9</td>', 'I only give out one 10 per challenge and you would have gotten it if the candle wasn''t quite as bright and distracting.  I think the border adds a nice touch.  9', '2003-09-10 18:48:52.000000', NULL, 1),
