(415092, 36938, 10833, '<td valign="top">Good shot in getting the picture in Direct sunlight without getting the windows "blown out".  however, this doesn''t pull at the nostalgia "hearstrongs" for me.</td>', 'Good shot in getting the picture in Direct sunlight without getting the windows "blown out".  however, this doesn''t pull at the nostalgia "hearstrongs" for me.', '2003-09-10 19:21:32.000000', NULL, 1),
(415093, 37059, 11506, '<td valign="top">You got a great idea, but it''s very hard to digitally photograph a video screen.  To capture the right levels of color while not showing the refresh rate of the screen is nearly impossible.  Hence your photo looks a bit washed out.  PS-  Nintendo kicked ass!</td>', 'You got a great idea, but it''s very hard to digitally photograph a video screen.  To capture the right levels of color while not showing the refresh rate of the screen is nearly impossible.  Hence your photo looks a bit washed out.  PS-  Nintendo kicked ass!', '2003-09-10 19:22:25.000000', NULL, 1),
(415095, 37138, 11506, '<td valign="top">I like this a lot.  Nice job.</td>', 'I like this a lot.  Nice job.', '2003-09-10 19:23:24.000000', NULL, 1),
(415096, 36559, 10833, '<td valign="top">I would have rated this higher if the picture had been in the same tones as the frame and letter.  The lighting seems a bit flat as well.<br/> <br/>That being said, I think it was a wonderful idea to use the letter along with the photograph.</td>', 'I would have rated this higher if the picture had been in the same tones as the frame and letter.  The lighting seems a bit flat as well. That being said, I think it was a wonderful idea to use the letter along with the photograph.', '2003-09-10 19:23:25.000000', NULL, 1),
(415098, 36970, 10833, '<td valign="top">Love hte tones in the hair, but the dark shadow around her ''left'' eye is a little distracting.</td>', 'Love hte tones in the hair, but the dark shadow around her ''left'' eye is a little distracting.', '2003-09-10 19:24:29.000000', NULL, 1),
