(415375, 36998, 6668, '<td valign="top">I fill that it would have made a better had you cropped the sky a little more, it is a bit overpowering in my opinion.</td>', 'I fill that it would have made a better had you cropped the sky a little more, it is a bit overpowering in my opinion.', '2003-09-10 23:33:52.000000', NULL, 1),
(415376, 36401, 10593, '<td valign="top">so cool!  i took the same picture last week while in nyc.  except mine doesnt have the cool light streaks as yours.</td>', 'so cool!  i took the same picture last week while in nyc.  except mine doesnt have the cool light streaks as yours.', '2003-09-10 23:34:17.000000', NULL, 1),
(415378, 36577, 11073, '<td valign="top">looks a little on the grainy side...did you resize or use the digital zoom?</td>', 'looks a little on the grainy side...did you resize or use the digital zoom?', '2003-09-10 23:36:32.000000', NULL, 1),
(415379, 37172, 6624, '<td valign="top">individuality lost...nostalgia for currency of home, lots of losses possible here...nice image</td>', 'individuality lost...nostalgia for currency of home, lots of losses possible here...nice image', '2003-09-10 23:37:28.000000', NULL, 1),
(415381, 36411, 6624, '<td valign="top">it''s a beauty - some loss of focus and it feels a bit crowded though</td>', 'it''s a beauty - some loss of focus and it feels a bit crowded though', '2003-09-10 23:38:36.000000', NULL, 1),
(415383, 36421, 11073, '<td valign="top">i like that you lead the "face"...i wouldn''t have thought to do that for an inanimate object...but it works to add interest.</td>', 'i like that you lead the "face"...i wouldn''t have thought to do that for an inanimate object...but it works to add interest.', '2003-09-10 23:39:12.000000', NULL, 1),
