(415387, 36921, 11073, '<td valign="top">nice shot...the dof works well here.</td>', 'nice shot...the dof works well here.', '2003-09-10 23:41:56.000000', NULL, 1),
(415388, 36817, 6668, '<td valign="top">Nice photo, personally I would have cropped a little bit more of the concrete away, I like the sepia tones also.</td>', 'Nice photo, personally I would have cropped a little bit more of the concrete away, I like the sepia tones also.', '2003-09-10 23:42:14.000000', NULL, 1),
(415390, 37142, 6668, '<td valign="top">Overall I really like this photo, the grass just seems a little oversaturated in my opinion.</td>', 'Overall I really like this photo, the grass just seems a little oversaturated in my opinion.', '2003-09-10 23:43:34.000000', NULL, 1),
