(417053, 37168, 12131, '<td valign="top">I feel bad for the guy having his picture taken with that expression and in that position.  Works though.</td>', 'I feel bad for the guy having his picture taken with that expression and in that position.  Works though.', '2003-09-12 16:11:35.000000', NULL, 1),
(417059, 36400, 12131, '<td valign="top">Very good, I like the method of seeing the future off in the distance while stuck in the past.  A lot is being said in this and you pull it off nicely.</td>', 'Very good, I like the method of seeing the future off in the distance while stuck in the past.  A lot is being said in this and you pull it off nicely.', '2003-09-12 16:13:25.000000', NULL, 1),
