(418374, 37206, 6900, '<td valign="top">The blues that make the gun look like that are disruptive in other parts of the picture - I''d try backing off them just a little.</td>', 'The blues that make the gun look like that are disruptive in other parts of the picture - I''d try backing off them just a little.', '2003-09-13 22:00:43.000000', NULL, 1),
(418375, 36516, 11432, '<td valign="top">Great capture.</td>', 'Great capture.', '2003-09-13 22:00:49.000000', NULL, 1),
(418384, 36516, 7706, '<td valign="top">This sh ot seems really soft, but it just works so well. Great job.</td>', 'This sh ot seems really soft, but it just works so well. Great job.', '2003-09-13 22:18:09.000000', NULL, 1),
(418386, 37174, 7706, '<td valign="top">The photo is alittle over exposed. I think if you play with brightness and contrast a little, you can generally fix a lot of that :)</td>', 'The photo is alittle over exposed. I think if you play with brightness and contrast a little, you can generally fix a lot of that :)', '2003-09-13 22:33:01.000000', NULL, 1),
(418388, 36958, 7706, '<td valign="top">I like the composition, bu the image seems a little dark to me. Love the pinkish tone. You should try Neat Image for noise reduction though :) It does wonders :)</td>', 'I like the composition, bu the image seems a little dark to me. Love the pinkish tone. You should try Neat Image for noise reduction though :) It does wonders :)', '2003-09-13 22:36:41.000000', NULL, 1),
(418389, 36952, 7706, '<td valign="top">I don''t mind the idea, but perhaps would have been better done indoors, where hopefully there would be no reflection on the glasses. Another way to avoid thatwould be to take the photo on a 45 degree angle</td>', 'I don''t mind the idea, but perhaps would have been better done indoors, where hopefully there would be no reflection on the glasses. Another way to avoid thatwould be to take the photo on a 45 degree angle', '2003-09-13 22:39:34.000000', NULL, 1),
(418392, 37230, 10883, '<td valign="top">Good picture!  If the other two watches had been brought a wee bit closer so the would not be so blurry, the pic would have been a bit better.  I give it an 8 though!  Good job!</td>', 'Good picture!  If the other two watches had been brought a wee bit closer so the would not be so blurry, the pic would have been a bit better.  I give it an 8 though!  Good job!', '2003-09-13 23:17:53.000000', NULL, 1),
(418395, 37151, 10883, '<td valign="top">There isn´t any one thing that really draws the eye too, and there is no real point which is interesting in the picture.  The pic should have been rotated a bit to correct the tilt and the crop does not do it for me.</td>', 'There isn´t any one thing that really draws the eye too, and there is no real point which is interesting in the picture.  The pic should have been rotated a bit to correct the tilt and the crop does not do it for me.', '2003-09-13 23:21:02.000000', NULL, 1),
(418396, 37220, 10883, '<td valign="top">The picture is grainy and the "crop" does not work well here.</td>', 'The picture is grainy and the "crop" does not work well here.', '2003-09-13 23:23:36.000000', NULL, 1),
(418397, 37142, 10883, '<td valign="top">The pic is a bit overexposed, the white geese lose a lot of detail.   Nice timing with the flying goose though...</td>', 'The pic is a bit overexposed, the white geese lose a lot of detail.   Nice timing with the flying goose though...', '2003-09-13 23:25:31.000000', NULL, 1),
(418398, 37191, 10883, '<td valign="top">In my opinion the pic would have been better if no one would have been up on the deck.</td>', 'In my opinion the pic would have been better if no one would have been up on the deck.', '2003-09-13 23:27:43.000000', NULL, 1),
(418401, 36621, 10883, '<td valign="top">Both the reflection on the screen and the stuff above the tv is distracting.  Unfortunately the pic does not interest me.</td>', 'Both the reflection on the screen and the stuff above the tv is distracting.  Unfortunately the pic does not interest me.', '2003-09-13 23:30:38.000000', NULL, 1),
