(419181, 37158, 12169, '<td valign="top">Nice set, good shadows, great content. Made me nostalgic.</td>', 'Nice set, good shadows, great content. Made me nostalgic.', '2003-09-15 03:31:41.000000', NULL, 1),
(419182, 36996, 12169, '<td valign="top">This is really good. GOod choice of subject, and you almost pulled off the old time look.</td>', 'This is really good. GOod choice of subject, and you almost pulled off the old time look.', '2003-09-15 03:34:11.000000', NULL, 1),
(419183, 37000, 12169, '<td valign="top">Ah!  there''s hope amongst all the darkness. Nice one.</td>', 'Ah!  there''s hope amongst all the darkness. Nice one.', '2003-09-15 03:35:57.000000', NULL, 1),
