(419190, 37002, 12169, '<td valign="top">Dang! At least you see the funny side of a bad situation. Great subject and excellent use of light and shadow.</td>', 'Dang! At least you see the funny side of a bad situation. Great subject and excellent use of light and shadow.', '2003-09-15 03:47:00.000000', NULL, 1),
