(419195, 36610, 12169, '<td valign="top">THat''s something special. Good everything.</td>', 'THat''s something special. Good everything.', '2003-09-15 03:52:08.000000', NULL, 1),
(419197, 37171, 12169, '<td valign="top">Good lighting, that''s about all.</td>', 'Good lighting, that''s about all.', '2003-09-15 03:53:02.000000', NULL, 1),
