INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(419208, 36639, 12169, '<td valign="top">Yeah cool if you know chess. Otherwise it''s a bit boring, you need more content in you photo.</td>', 'Yeah cool if you know chess. Otherwise it''s a bit boring, you need more content in you photo.', '2003-09-15 04:04:14.000000', NULL, 1),
(419209, 36729, 12169, '<td valign="top">It''s a little unclear what you want the centre of attention to be. The darks are a little too dark and the lights are a little too white.</td>', 'It''s a little unclear what you want the centre of attention to be. The darks are a little too dark and the lights are a little too white.', '2003-09-15 04:07:04.000000', NULL, 1),
(419210, 37198, 12169, '<td valign="top">Very nostalgic. What are you trying to say? Sharp image on it though.</td>', 'Very nostalgic. What are you trying to say? Sharp image on it though.', '2003-09-15 04:09:34.000000', NULL, 1),
(419211, 36701, 12169, '<td valign="top">Not bad composition. What''s a ''Dairy Queer''?</td>', 'Not bad composition. What''s a ''Dairy Queer''?', '2003-09-15 04:11:27.000000', NULL, 1),
(419212, 36609, 12169, '<td valign="top">All hail macro. Wicked shodow, cool content.</td>', 'All hail macro. Wicked shodow, cool content.', '2003-09-15 04:12:56.000000', NULL, 1),
(419218, 37149, 12169, '<td valign="top">Very cool!! Excellent light, shadows, reflections, and use of colours. Good content aswell.</td>', 'Very cool!! Excellent light, shadows, reflections, and use of colours. Good content aswell.', '2003-09-15 04:26:38.000000', NULL, 1),
(419219, 37130, 12169, '<td valign="top">This is a excellent concept and well executed. I like the colour and lighting.</td>', 'This is a excellent concept and well executed. I like the colour and lighting.', '2003-09-15 04:29:02.000000', NULL, 1),
(419220, 36766, 12169, '<td valign="top">Too much emotion. Clean photo though.</td>', 'Too much emotion. Clean photo though.', '2003-09-15 04:30:42.000000', NULL, 1),
(419273, 36351, 9809, '<td valign="top">too narrow of a DOF -- lots of blur in this photo.</td>', 'too narrow of a DOF -- lots of blur in this photo.', '2003-09-15 06:59:38.000000', NULL, 1),
(419280, 36634, 9809, '<td valign="top">The harsh lighting from the window on the left has blown out the book or whatever on the table and the lower left total darkness makes me wonder what I\''m missing there -- the only problems I see with this photo. Perfect shutter speed to show the wheel in motion but yet let us see there are definite spokes there. I give it a 9!</td>', 'The harsh lighting from the window on the left has blown out the book or whatever on the table and the lower left total darkness makes me wonder what I\''m missing there -- the only problems I see with this photo. Perfect shutter speed to show the wheel in motion but yet let us see there are definite spokes there. I give it a 9!', '2003-09-15 07:13:37.000000', NULL, 1),
(419281, 36553, 9809, '<td valign="top">Is this the same woman? I think so! It looks like the same doorway too. I wish you had pulled back a bit to see more of the frame like in the original, but the message is still clear the way it is. If I could see more of the door frame and step I''d give it a 10, but as is, it''s a 9.</td>', 'Is this the same woman? I think so! It looks like the same doorway too. I wish you had pulled back a bit to see more of the frame like in the original, but the message is still clear the way it is. If I could see more of the door frame and step I''d give it a 10, but as is, it''s a 9.', '2003-09-15 07:15:25.000000', NULL, 1),
(419282, 36400, 9809, '<td valign="top">Great composition. The colors are wonderful -- the blue of the water, the green of the gunnel are striking. I wish there were more light to show off the color (yellow?) of the boat. I''m having a hard time seeing the "Nostalgia" in this image, but I''m betting that is just because of a cultural barrier -- I''m going to just rate the picture as if it IS somehow nostalgic. I give it a 9 -- it would be a 10 if I could see the boat a bit better.</td>', 'Great composition. The colors are wonderful -- the blue of the water, the green of the gunnel are striking. I wish there were more light to show off the color (yellow?) of the boat. I''m having a hard time seeing the "Nostalgia" in this image, but I''m betting that is just because of a cultural barrier -- I''m going to just rate the picture as if it IS somehow nostalgic. I give it a 9 -- it would be a 10 if I could see the boat a bit better.', '2003-09-15 07:15:46.000000', NULL, 1),
(419283, 37173, 9809, '<td valign="top">Nothing like old photos to remind of when... Nostalgia meter at 90%...<br/> <br/>Good depth of field, nicely arranged. My eye tends to wander around the image taking in all the individual shots. I guess that is supposed to be technically bad, but it works for me -- thank God I don''t know what I''m doing.  This is my favorite so far, but I''ve only looked at a couple dozen.<br/> <br/>I''ve looked at them all... and I''m back. Still a nine. Nice work.</td>', 'Nothing like old photos to remind of when... Nostalgia meter at 90%... Good depth of field, nicely arranged. My eye tends to wander around the image taking in all the individual shots. I guess that is supposed to be technically bad, but it works for me -- thank God I don''t know what I''m doing.  This is my favorite so far, but I''ve only looked at a couple dozen. I''ve looked at them all... and I''m back. Still a nine. Nice work.', '2003-09-15 07:17:08.000000', NULL, 1),
(419284, 36589, 9809, '<td valign="top">Excellent memory; Nostalgia meter at 100% and I think done in a universal manner that everyone of various cultures will get. The DOF is excellent. I like the slight blur on the foreground of the ring but the sharpness of the inside plus the photo in the background. In my top 5 so far. After reviewing all the photos, this still ended up near the top. I''ll stick firm with the 9 rating.</td>', 'Excellent memory; Nostalgia meter at 100% and I think done in a universal manner that everyone of various cultures will get. The DOF is excellent. I like the slight blur on the foreground of the ring but the sharpness of the inside plus the photo in the background. In my top 5 so far. After reviewing all the photos, this still ended up near the top. I''ll stick firm with the 9 rating.', '2003-09-15 07:18:08.000000', NULL, 1),
(419288, 37209, 7689, '<td valign="top">Though the shine on the seats and counter is a little distracting but nice DOF... good composition...</td>', 'Though the shine on the seats and counter is a little distracting but nice DOF... good composition...', '2003-09-15 07:29:49.000000', NULL, 1),
(419311, 37100, 10370, '<td valign="top">Fan-bloomin-tastic ! 9 <br/>I''d love to see it blown up really big! Great poster</td>', 'Fan-bloomin-tastic ! 9 I''d love to see it blown up really big! Great poster', '2003-09-15 09:05:39.000000', NULL, 1),
(419327, 36589, 7689, '<td valign="top">whole picture in sephi would have looked nice.. still nice composition and idea.</td>', 'whole picture in sephi would have looked nice.. still nice composition and idea.', '2003-09-15 09:41:44.000000', NULL, 1),
(419346, 37151, 7689, '<td valign="top">nice composition and color.... still too pink for my taste.</td>', 'nice composition and color.... still too pink for my taste.', '2003-09-15 10:00:42.000000', NULL, 1),
(419353, 37204, 3724, '<td valign="top">Painted wall....  love those bumper cars....  great subject.  The baseball card size bothers me a little bit though, I wish it was sized larger.</td>', 'Painted wall....  love those bumper cars....  great subject.  The baseball card size bothers me a little bit though, I wish it was sized larger.', '2003-09-15 10:10:50.000000', NULL, 1),
(419364, 37144, 3724, '<td valign="top">Old cinema.....  I am drawn to  this sad image.  Interesting document of this kind of fading architecture.  Picture show perfect subject for this challenge.</td>', 'Old cinema.....  I am drawn to  this sad image.  Interesting document of this kind of fading architecture.  Picture show perfect subject for this challenge.', '2003-09-15 10:19:43.000000', NULL, 1),
(419388, 36819, 10799, '<td valign="top">Nice but very small</td>', 'Nice but very small', '2003-09-15 10:36:48.000000', NULL, 1),
(419395, 37122, 10799, '<td valign="top">Grandma would have starched and ironed that dresser scarf before she let you take pictures of it.  :)  Really, that would help the picture to get rid of the distraction of the wrinkles.  Very creative thought... good idea.</td>', 'Grandma would have starched and ironed that dresser scarf before she let you take pictures of it.  :)  Really, that would help the picture to get rid of the distraction of the wrinkles.  Very creative thought... good idea.', '2003-09-15 10:42:04.000000', NULL, 1),
(419425, 37191, 4615, '<td valign="top">priceles.</td>', 'priceles.', '2003-09-15 10:57:24.000000', NULL, 1),
(419436, 37185, 4615, '<td valign="top">better w/ the fat lady.</td>', 'better w/ the fat lady.', '2003-09-15 11:00:58.000000', NULL, 1),
(419474, 36489, 4517, '<td valign="top">Good idea but could be sharper.</td>', 'Good idea but could be sharper.', '2003-09-15 11:18:39.000000', NULL, 1),
(419480, 37119, 10883, '<td valign="top">The pic is a bit noisy...  The person on the left detracts a bit from the picture in my opinion!<br/>Very cool rainbow!</td>', 'The pic is a bit noisy...  The person on the left detracts a bit from the picture in my opinion!Very cool rainbow!', '2003-09-15 11:21:58.000000', NULL, 1),
(419481, 36680, 10883, '<td valign="top">Nice shapes!</td>', 'Nice shapes!', '2003-09-15 11:22:26.000000', NULL, 1),
(419533, 37219, 2764, '<td valign="top">the curtains and the light are lovely - maybe you could crop out the front edge of the table to emphasize them -  we don''t need the whole desk and the whole paper, it makes the composition too straight on.  The main elements are the pencil trough in the desk, the headline and the lace.</td>', 'the curtains and the light are lovely - maybe you could crop out the front edge of the table to emphasize them -  we don''t need the whole desk and the whole paper, it makes the composition too straight on.  The main elements are the pencil trough in the desk, the headline and the lace.', '2003-09-15 11:38:57.000000', NULL, 1),
(419542, 36351, 2764, '<td valign="top">this is like a trick photo - my brain won''t make it lie flat - what is in the background and what in the foreground.  on the right, the horizontal book in in front but on the left the blurry stuff that is not boks wants to come forwards - also the top of gospels 1 is doing something funny in space.  It''s making me dizzzy.</td>', 'this is like a trick photo - my brain won''t make it lie flat - what is in the background and what in the foreground.  on the right, the horizontal book in in front but on the left the blurry stuff that is not boks wants to come forwards - also the top of gospels 1 is doing something funny in space.  It''s making me dizzzy.', '2003-09-15 11:43:11.000000', NULL, 1),
(419555, 37141, 10883, '<td valign="top">The pic is overexposed and way too busy.</td>', 'The pic is overexposed and way too busy.', '2003-09-15 11:48:47.000000', NULL, 1),
(419558, 36600, 2764, '<td valign="top">more pixels please</td>', 'more pixels please', '2003-09-15 11:49:16.000000', NULL, 1),
(419559, 37033, 2764, '<td valign="top">more pixels please</td>', 'more pixels please', '2003-09-15 11:49:29.000000', NULL, 1),
(419561, 36498, 2764, '<td valign="top">the contrast seems so harsh for the subject.  shouldn''t babies and memories and nostalgia have a softer tone?</td>', 'the contrast seems so harsh for the subject.  shouldn''t babies and memories and nostalgia have a softer tone?', '2003-09-15 11:52:33.000000', NULL, 1),
(419562, 36805, 2764, '<td valign="top">wow</td>', 'wow', '2003-09-15 11:53:27.000000', NULL, 1),
(419565, 37142, 2764, '<td valign="top">could you crop out that big box on the right?  I also wish the geese werre''t so over exposed.  It''s almost a beautiful image.</td>', 'could you crop out that big box on the right?  I also wish the geese werre''t so over exposed.  It''s almost a beautiful image.', '2003-09-15 11:56:16.000000', NULL, 1),
(419566, 36555, 2764, '<td valign="top">more pixels please</td>', 'more pixels please', '2003-09-15 11:56:47.000000', NULL, 1),
(419572, 36948, 2764, '<td valign="top">border out weighs the image</td>', 'border out weighs the image', '2003-09-15 12:02:03.000000', NULL, 1),
(419587, 37231, 3343, '<td valign="top">Outstanding - 10</td>', 'Outstanding - 10', '2003-09-15 12:16:50.000000', NULL, 1),
(419633, 36972, 6008, '<td valign="top">I like this as a wonderfully dated image. The contrasts are great, which with black and white is so very important. Compositionally it is great, the lines and curves leading the eye naturally around the image. It doesnt really conjure up any nostalgic feeling from me personally, but I''m sure it may with some people. Excellent photograph.</td>', 'I like this as a wonderfully dated image. The contrasts are great, which with black and white is so very important. Compositionally it is great, the lines and curves leading the eye naturally around the image. It doesnt really conjure up any nostalgic feeling from me personally, but I''m sure it may with some people. Excellent photograph.', '2003-09-15 13:08:51.000000', NULL, 1),
(419657, 36921, 6008, '<td valign="top">There is a wonderful humor in this image, and I believe that the majority of people (at least those over a certain age) have done this exact thing in one way or another. It is the familiar reference that I think most people, myself included, relate to, and which is why the impression that the image leaves surpasses any flaws that may be in the shot. In the end I dont think it matters if this or that is out of place or anything else. What it delivers to the viewer and leaves as a lasting impression is a (hopefully) happy memory, which is exactly what the challenge was trying to do.</td>', 'There is a wonderful humor in this image, and I believe that the majority of people (at least those over a certain age) have done this exact thing in one way or another. It is the familiar reference that I think most people, myself included, relate to, and which is why the impression that the image leaves surpasses any flaws that may be in the shot. In the end I dont think it matters if this or that is out of place or anything else. What it delivers to the viewer and leaves as a lasting impression is a (hopefully) happy memory, which is exactly what the challenge was trying to do.', '2003-09-15 13:25:49.000000', NULL, 1),
(419666, 37214, 6008, '<td valign="top">Such a simple image, but one that works well, at least for me personally, because it does conjure up images of the past, and fond memories even though they were frustrating at the time. The lighting is good, the composition is great, I have no idea what the things are on the ends but they look funky. The only thing I dont really care about is the blue patch at the bottom, which I''m guessing is due to the light beam falling on the felt, although it does give it some perspective of being placed on something and not just floating in the air. Great shot!</td>', 'Such a simple image, but one that works well, at least for me personally, because it does conjure up images of the past, and fond memories even though they were frustrating at the time. The lighting is good, the composition is great, I have no idea what the things are on the ends but they look funky. The only thing I dont really care about is the blue patch at the bottom, which I''m guessing is due to the light beam falling on the felt, although it does give it some perspective of being placed on something and not just floating in the air. Great shot!', '2003-09-15 13:29:57.000000', NULL, 1),
(419678, 37022, 6008, '<td valign="top">This has a nice calm and serene feel to it. Although I''ve never sat on a rocker on a porch I have seen it in many television shows/movies and it does bring those memories to me. The sepia ages it well. The first rocker (the one without the cover) seems to blend in to the screen/window a little too much because of the similar tones - I would have liked a little more light or contrast with it to really bring it out. That said, it would have been interesting to have just one of the rockers there instead also. Some things are better shared, but maybe having just one may have put more of a solitary feel and mood to it. Just some thoughts. Because of the brightness to the left with the foliage, the shadows do look a little dark, but not necessarily overly problematic, at least not on the one with the cover. A nice image!</td>', 'This has a nice calm and serene feel to it. Although I''ve never sat on a rocker on a porch I have seen it in many television shows/movies and it does bring those memories to me. The sepia ages it well. The first rocker (the one without the cover) seems to blend in to the screen/window a little too much because of the similar tones - I would have liked a little more light or contrast with it to really bring it out. That said, it would have been interesting to have just one of the rockers there instead also. Some things are better shared, but maybe having just one may have put more of a solitary feel and mood to it. Just some thoughts. Because of the brightness to the left with the foliage, the shadows do look a little dark, but not necessarily overly problematic, at least not on the one with the cover. A nice image!', '2003-09-15 13:36:41.000000', NULL, 1),
(419682, 36553, 6008, '<td valign="top">At first glance I wasnt too sure about this image. I thought perhaps it was someone mourning the loss of a daughter/sister/relative/friend, probably coupled with the expression of sadness on her face. Then I realised that the door in the photograph was the same as in the image. I''m still not sure if it was my first initial feeling or whether it is an image of someone holding a photograph of themselves X number of years later. I''ve chosen to believe the second, as I feel that has more of an impact on me than the first. Reflecting back and mourning the passing of time is a really emotional issue. The happy pose of the girl suggests innocence and curiosity and the older woman shows life experience and possible hardships. The same yet different. I really like this image and enjoy it on many levels. It has made me think, and to do that is always a good thing. Thank you.</td>', 'At first glance I wasnt too sure about this image. I thought perhaps it was someone mourning the loss of a daughter/sister/relative/friend, probably coupled with the expression of sadness on her face. Then I realised that the door in the photograph was the same as in the image. I''m still not sure if it was my first initial feeling or whether it is an image of someone holding a photograph of themselves X number of years later. I''ve chosen to believe the second, as I feel that has more of an impact on me than the first. Reflecting back and mourning the passing of time is a really emotional issue. The happy pose of the girl suggests innocence and curiosity and the older woman shows life experience and possible hardships. The same yet different. I really like this image and enjoy it on many levels. It has made me think, and to do that is always a good thing. Thank you.', '2003-09-15 13:43:31.000000', NULL, 1),
(419685, 36947, 6008, '<td valign="top">I''ve seen a few villages like this throughout my life, and as such it does bring back memories for me. The sepia ages it well, although I would have liked a little more contrast as the tonal range is all very similar, except for the foliage. Compositionally it''s good and the line of cottages naturally leads the eye up to the others on the hill. A very nice shot.</td>', 'I''ve seen a few villages like this throughout my life, and as such it does bring back memories for me. The sepia ages it well, although I would have liked a little more contrast as the tonal range is all very similar, except for the foliage. Compositionally it''s good and the line of cottages naturally leads the eye up to the others on the hill. A very nice shot.', '2003-09-15 13:47:06.000000', NULL, 1),
(419689, 37081, 6008, '<td valign="top">Although the references are lost on me (I''m not American nor did I play baseball as a child), I can appreciate that this does speak of a time past and likely is very nostalgic to the specific audience that it caters to. It''s a wonderful still life and has elements of everything arranged nicely in an appealing composition. It certainly screams nostalgia, but it is visually appealing as an image outside of the challenge also.</td>', 'Although the references are lost on me (I''m not American nor did I play baseball as a child), I can appreciate that this does speak of a time past and likely is very nostalgic to the specific audience that it caters to. It''s a wonderful still life and has elements of everything arranged nicely in an appealing composition. It certainly screams nostalgia, but it is visually appealing as an image outside of the challenge also.', '2003-09-15 13:52:45.000000', NULL, 1),
(419700, 36746, 4517, '<td valign="top">Great colour saturation.</td>', 'Great colour saturation.', '2003-09-15 14:02:10.000000', NULL, 1),
