(420381, 37055, 6172, '<td valign="top">Looks just a little staged...</td>', 'Looks just a little staged...', '2003-09-16 05:07:00.000000', NULL, 1),
(420382, 36822, 6172, '<td valign="top">Nice job on this.  Nice effect with the rusty red engine.  The sky is pixelated, however, you probably overprocessed the photo I''m guessing.</td>', 'Nice job on this.  Nice effect with the rusty red engine.  The sky is pixelated, however, you probably overprocessed the photo I''m guessing.', '2003-09-16 05:10:54.000000', NULL, 1),
(420384, 37212, 6172, '<td valign="top">Yeah I do!  Just I didn''t travel along the railroad, it was a nearby lake.  Great job with the color, and I like your choice to leave a large empty space in the foreground - it gives me the impression that the little boy has traveled a ways.  This is one of my faves in this challenge.</td>', 'Yeah I do!  Just I didn''t travel along the railroad, it was a nearby lake.  Great job with the color, and I like your choice to leave a large empty space in the foreground - it gives me the impression that the little boy has traveled a ways.  This is one of my faves in this challenge.', '2003-09-16 05:13:43.000000', NULL, 1),
(420385, 37224, 6172, '<td valign="top">Not very good focus in this photo, and too much glare from the lamp - a polarizing filter would''ve helped a lot.</td>', 'Not very good focus in this photo, and too much glare from the lamp - a polarizing filter would''ve helped a lot.', '2003-09-16 05:15:29.000000', NULL, 1),
(420388, 36795, 6172, '<td valign="top">I like the background and whatever you did to make this photo look like it does ( a filter in photoshop? maybe even an illegal editing action).  Why didn''t you show more of the machine?</td>', 'I like the background and whatever you did to make this photo look like it does ( a filter in photoshop? maybe even an illegal editing action).  Why didn''t you show more of the machine?', '2003-09-16 05:17:32.000000', NULL, 1),
(420390, 36729, 6172, '<td valign="top">A very personal interpetation of this challenge, and also a valid and interesting one.  I like the lighting (or lack thereof?).</td>', 'A very personal interpetation of this challenge, and also a valid and interesting one.  I like the lighting (or lack thereof?).', '2003-09-16 05:19:42.000000', NULL, 1),
(420391, 37028, 6172, '<td valign="top">Seems like the slinkies in the back aren''t focused as well.  I like this shot, nice subject and the composition is pretty good.  Are those slinkies worth money now?</td>', 'Seems like the slinkies in the back aren''t focused as well.  I like this shot, nice subject and the composition is pretty good.  Are those slinkies worth money now?', '2003-09-16 05:21:37.000000', NULL, 1),
(420395, 36538, 11405, '<td valign="top">Cool framing of this W48. Nice colouring. The original is only black. Great.</td>', 'Cool framing of this W48. Nice colouring. The original is only black. Great.', '2003-09-16 05:54:02.000000', NULL, 1),
(420403, 37213, 8274, '<td valign="top">Up until this picture this had been a rather uncreative challenge..well done !</td>', 'Up until this picture this had been a rather uncreative challenge..well done !', '2003-09-16 07:54:10.000000', NULL, 1),
