INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(420428, 36759, 7689, '<td valign="top">a little dull in clarity but nice thought... Better lighting would make it nicer.</td>', 'a little dull in clarity but nice thought... Better lighting would make it nicer.', '2003-09-16 09:19:42.000000', NULL, 1),
(420430, 37166, 7689, '<td valign="top">still used these days in western pensylvania and many states.... nice thought though. A little overexposed too.</td>', 'still used these days in western pensylvania and many states.... nice thought though. A little overexposed too.', '2003-09-16 09:20:52.000000', NULL, 1),
(420432, 36653, 7689, '<td valign="top">Hmmmm I thought of this one but good that I did not submit a similar entry.</td>', 'Hmmmm I thought of this one but good that I did not submit a similar entry.', '2003-09-16 09:21:43.000000', NULL, 1),
(420433, 36733, 7689, '<td valign="top">Hmmm where did you find this oldie..</td>', 'Hmmm where did you find this oldie..', '2003-09-16 09:23:03.000000', NULL, 1),
(420436, 37142, 7689, '<td valign="top">ducks seem a little overexposed...</td>', 'ducks seem a little overexposed...', '2003-09-16 09:34:58.000000', NULL, 1),
(420444, 37053, 8860, '<td valign="top">Oooh that looks comfy - I''m sure I''ve slept in that bed before. :D<br/> <br/>I remember those days too - but my Dad gets fed up if I do it now coz there''s not much room now. Great shot with lovely DOF. Could have straightened it up a bit though!</td>', 'Oooh that looks comfy - I''m sure I''ve slept in that bed before. :D I remember those days too - but my Dad gets fed up if I do it now coz there''s not much room now. Great shot with lovely DOF. Could have straightened it up a bit though!', '2003-09-16 09:59:17.000000', NULL, 1),
(420445, 37130, 8860, '<td valign="top">I''d like to have seen a more interesting view of this - perhaps really low with some detail in the grooves and stylus? Distracting shine off the left of the disc. Nice composition and focus, but not much going on to hold the attention for long.</td>', 'I''d like to have seen a more interesting view of this - perhaps really low with some detail in the grooves and stylus? Distracting shine off the left of the disc. Nice composition and focus, but not much going on to hold the attention for long.', '2003-09-16 10:01:55.000000', NULL, 1),
(420447, 36680, 8860, '<td valign="top">Nice detail. Smooth lighting and tones. Border is distracting and too close to the subject of interest. The detail shows some lovely workmanship.</td>', 'Nice detail. Smooth lighting and tones. Border is distracting and too close to the subject of interest. The detail shows some lovely workmanship.', '2003-09-16 10:04:48.000000', NULL, 1),
(420452, 37226, 8860, '<td valign="top">Well, that''s my preferred option for the solution! Image lacks atmosphere and is a bit bland. Some directional lighting would help and straightening the image to vertical would be good.</td>', 'Well, that''s my preferred option for the solution! Image lacks atmosphere and is a bit bland. Some directional lighting would help and straightening the image to vertical would be good.', '2003-09-16 10:08:12.000000', NULL, 1),
