(422380, 36862, 11738, '<td valign="top">Wow!  47th out of the lot!  My goal was to finish within the top 50%.  Being a numbers guy, I had to calculate it... I''m in the top 19%.  Double woohoo!<br/> <br/>Thanks for the votes and the comments!</td>', 'Wow!  47th out of the lot!  My goal was to finish within the top 50%.  Being a numbers guy, I had to calculate it... I''m in the top 19%.  Double woohoo! Thanks for the votes and the comments!', '2003-09-17 21:22:48.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(422441, 37231, 1717, '<td valign="top">congratulations!  great pic!</td>', 'congratulations!  great pic!', '2003-09-17 22:04:48.000000', NULL, 0),
(422454, 36553, 11769, '<td valign="top">Thank you for all the wonderful comments. This is the first time I have entered a challenge of any sort as I have just begun my adventures in photography, being mainly a Painter, Fine Art. The idea of the photograph was a sudden insperation, noone has passed away.(Noone has been harmed in the making of this potograph).<br/>                                          Thanks again</td>', 'Thank you for all the wonderful comments. This is the first time I have entered a challenge of any sort as I have just begun my adventures in photography, being mainly a Painter, Fine Art. The idea of the photograph was a sudden insperation, noone has passed away.(Noone has been harmed in the making of this potograph).                                          Thanks again', '2003-09-17 22:30:51.000000', NULL, 0),
(422463, 37231, 259, '<td valign="top">thanks to all for the comments.  like many people mentioned, the reflection isn''t all there, and i almost didn''t submit this pic because of that.  i had some others that did include it, but were portrait and didn''t include the bridge.  i guess it''s a good thing i went back and chose this one.</td>', 'thanks to all for the comments.  like many people mentioned, the reflection isn''t all there, and i almost didn''t submit this pic because of that.  i had some others that did include it, but were portrait and didn''t include the bridge.  i guess it''s a good thing i went back and chose this one.', '2003-09-17 22:46:26.000000', NULL, 0),
(422485, 37231, 10263, '<td valign="top">Grats on the ribbon. nice photo :)</td>', 'Grats on the ribbon. nice photo :)', '2003-09-17 22:59:23.000000', NULL, 0),
(422517, 36822, 6405, '<td valign="top">Very nice photo,good colors choice make this thing look even older!<br/>You got my 10 on this one and I''m happy that was yours! :-)</td>', 'Very nice photo,good colors choice make this thing look even older!You got my 10 on this one and I''m happy that was yours! :-)', '2003-09-17 23:25:41.000000', NULL, 0),
(422619, 37209, 92, '<td valign="top">Congrats on a well deserved win ! This is done perfectly. I love the light sepia tone.<br/> <br/></td>', 'Congrats on a well deserved win ! This is done perfectly. I love the light sepia tone. ', '2003-09-18 01:42:12.000000', NULL, 0),
(422638, 36412, 11073, '<td valign="top">I had given you a six on this picture.  It''s a shame that you scored so low - my guess is that your image was too small...If you need help resizing, click on Learn -- Tutorials above.  I really like the atmospheric element in this picture and I think that the tree is framed well.  I totally get the connection to nostalgia.  Whenever I see pictures of the house from long ago and see the tree that were there when I was little....just wanted to say that I liked your pic.</td>', 'I had given you a six on this picture.  It''s a shame that you scored so low - my guess is that your image was too small...If you need help resizing, click on Learn -- Tutorials above.  I really like the atmospheric element in this picture and I think that the tree is framed well.  I totally get the connection to nostalgia.  Whenever I see pictures of the house from long ago and see the tree that were there when I was little....just wanted to say that I liked your pic.', '2003-09-18 02:23:49.000000', NULL, 0),
(422832, 36862, 12321, '<td valign="top">sucessfully evokes a mood, great composition, has a professional look</td>', 'sucessfully evokes a mood, great composition, has a professional look', '2003-09-18 09:54:54.000000', NULL, 0),
(422836, 37209, 12321, '<td valign="top">this is a nice shot for sure, but compositionally i want some focal point to lure my eye back in....right now my eyes appreciate the repetition and graphic nature of this pic, but my eyes just slide right over the seats and out of the shot.  when viewing this pic your eye does not come to rest on anything. i believe the lack of focal point keeps this exceptional shot just shy of greatness.</td>', 'this is a nice shot for sure, but compositionally i want some focal point to lure my eye back in....right now my eyes appreciate the repetition and graphic nature of this pic, but my eyes just slide right over the seats and out of the shot.  when viewing this pic your eye does not come to rest on anything. i believe the lack of focal point keeps this exceptional shot just shy of greatness.', '2003-09-18 10:07:04.000000', NULL, 0),
(422837, 37231, 92, '<td valign="top">This is so beautiful. I love the lighting and reflection. Congrats on your win !</td>', 'This is so beautiful. I love the lighting and reflection. Congrats on your win !', '2003-09-18 10:07:17.000000', NULL, 0),
(423282, 37226, 10720, '<td valign="top">Amazing how many people remembered those days, although some did not get it as following the theme. I knew when I entered that it would have a nostalgic feel only to people from a certain age/personaility/countries (I am not sure how big the cube was world-wide). <br/> <br/>The picture was straight but to get the screwdriver to stand up it leaned slightly, since that is the longest line in the photo makes it look unballanced. What I should have done is made the screwdriver straight. (lesson 1 learned).<br/> <br/> <br/>I know I need to work on lightening techniques, (lesson to be learned) plus I should have played with the color levels a bit to see if I could not get the colors to POP a bit more. (another lesson still to be learned)<br/> <br/>This is an original cube and later editions had more color contrast. Plus the cube is wounded so I had limited choices of what side to show.</td>', 'Amazing how many people remembered those days, although some did not get it as following the theme. I knew when I entered that it would have a nostalgic feel only to people from a certain age/personaility/countries (I am not sure how big the cube was world-wide).  The picture was straight but to get the screwdriver to stand up it leaned slightly, since that is the longest line in the photo makes it look unballanced. What I should have done is made the screwdriver straight. (lesson 1 learned).  I know I need to work on lightening techniques, (lesson to be learned) plus I should have played with the color levels a bit to see if I could not get the colors to POP a bit more. (another lesson still to be learned) This is an original cube and later editions had more color contrast. Plus the cube is wounded so I had limited choices of what side to show.', '2003-09-18 16:53:49.000000', NULL, 0),
(423301, 36947, 6999, '<td valign="top">meant to comment on this during the challenge, but never managed to get back to it. So many shots in this challenge were simply of old things - and on the face of it, so is this: but your toning, and the absence of people, or to my eye any sign of human activity after the building of these houses, puts it into a more meaningful category - saying something of the loss and other feelings inherent in the title of the challenge. Good work.</td>', 'meant to comment on this during the challenge, but never managed to get back to it. So many shots in this challenge were simply of old things - and on the face of it, so is this: but your toning, and the absence of people, or to my eye any sign of human activity after the building of these houses, puts it into a more meaningful category - saying something of the loss and other feelings inherent in the title of the challenge. Good work.', '2003-09-18 17:21:11.000000', NULL, 0),
(423397, 37155, 12341, '<td valign="top">cool picture!!!</td>', 'cool picture!!!', '2003-09-18 18:21:23.000000', NULL, 0),
(423437, 36516, 4793, '<td valign="top">This is definately one of the nicest shots in the Nostalgia challenge, it is simple and un-cluttered, a very artistic shot. Thanks for sharing a beautiful scene with us.</td>', 'This is definately one of the nicest shots in the Nostalgia challenge, it is simple and un-cluttered, a very artistic shot. Thanks for sharing a beautiful scene with us.', '2003-09-18 18:52:28.000000', NULL, 0),
